def minPath(grid, k):
    m, n = len(grid), len(grid[0])
    visited = set()
    queue = deque([(i, j, [grid[i][j]]) for i in range(m) for j in range(n)])
    res = None

    while queue:
        x, y, path = queue.popleft()
        if len(path) == k:
            if res is None or path < res:
                res = path
            continue
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, path + [grid[nx][ny]]))
    return res if res else [1] * k

